#include <stdio.h>

typedef struct
{
    int key;
    int tag;
} Rec;

int main(void)
{
    Rec a[6] = {{3,1},{1,2},{3,3},{2,4},{1,5},{4,6}};
    int n = 6, i, j, flag, cmp = 0, swp = 0;

    for (i = 0; i < n - 1; i++)
    {
        flag = 0;
        for (j = 0; j < n - 1 - i; j++)
        {
            cmp++;
            if (a[j].key > a[j + 1].key)
            {
                Rec t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swp++;
                flag = 1;
            }
        }
        if (flag == 0)
            break;
    }
    for (i = 0; i < n; i++)
        printf("%d/%d ", a[i].key, a[i].tag);
    printf("\n%d %d\n", cmp, swp);
    return 0;
}
